fn replacement<T>(
    old: &Vec<T>, target: usize, control: &mut PaintControl<'"'_>, offset: usize,
) -> Result<Option<Replacement<T>>> {
    if old.capacity() >= target { return Ok(None); }
    let size = std::mem::size_of::<T>();
    let requested = target.checked_mul(size).ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
    if requested > control.ledger.available() { return Err(limit(LimitKind::ReservedBytes, offset)); }
