    let new_bytes = values.capacity().checked_mul(size).ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
    let old_bytes = old.capacity().checked_mul(size).ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
    let lease = control.ledger.admit(AllocationTag::None, new_bytes)?;
    Ok(Some(Replacement { values, lease, old_bytes, new_bytes }))
}

fn reconcile<T>(buffer: &Replacement<T>, control: &mut PaintControl<'_>) -> Result<()> {
    control.ledger.release(buffer.lease)?;
    let _job_lease = control.ledger.admit(AllocationTag::None, buffer.new_bytes - buffer.old_bytes)?;
    Ok(())
