    let mut entries = match replacement(&cache.entries, target_entries, control, offset) {
        Ok(value) => value,
        Err(error) => {
            if let Some(buffer) = slots { control.ledger.release(buffer.lease)?; }
            return Err(error);
        }
    };
    // Every fallible control operation precedes cache mutation.
    let prepared = (|| {
        for bytes in [
            if slots.is_some() { cache.slots.len().checked_mul(std::mem::size_of::<Option<usize>>()) } else { Some(0) },
            if entries.is_some() { cache.entries.len().checked_mul(std::mem::size_of::<GradientCacheEntry>()) } else { Some(0) },
        ] {
            let mut bytes = bytes.ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
            while bytes != 0 {
                let batch = bytes.min(256);
                control.charge(WorkKind::SourceRead, batch as u64)
                    .map_err(|_| limit(LimitKind::Work, offset))?;
                bytes -= batch;
            }
        }
        control.checkpoint().map_err(|_| limit(LimitKind::Work, offset))
    })();
    if let Err(error) = prepared {
        if let Some(buffer) = slots { control.ledger.release(buffer.lease)?; }
        if let Some(buffer) = entries { control.ledger.release(buffer.lease)?; }
        return Err(error);
    }
    // The full replacements were admitted during overlap. Retain only their
    // growth after old metadata is dropped; previously admitted job capacities
    // remain represented by the old job leases.
    if let Some(buffer) = &slots { reconcile(buffer, control)?; }
    if let Some(buffer) = &entries { reconcile(buffer, control)?; }
    if let Some(mut buffer) = slots.take() {
        buffer.values.append(&mut cache.slots);
        cache.slots = buffer.values;
    }
    if let Some(mut buffer) = entries.take() {
        buffer.values.append(&mut cache.entries);
        cache.entries = buffer.values;
    }
    cache.slots.resize(CACHE_SLOTS, None);
    let index = cache.entries.len();
    cache.entries.push(GradientCacheEntry {
        definition, context: template_context(viewport), paint,
        stop_range: paint.stops, stops, source: Arc::clone(source),
    });
    cache.slots[slot] = Some(index);
    Ok(index)
}

struct Replacement<T> {
    values: Vec<T>,
    lease: vexel_scene::AllocationLease,
    old_bytes: usize,
    new_bytes: usize,
}

fn replacement<T>(
    old: &Vec<T>, target: usize, control: &mut PaintControl<'"'_>, offset: usize,
) -> Result<Option<Replacement<T>>> {
    if old.capacity() >= target { return Ok(None); }
    let size = std::mem::size_of::<T>();
    let requested = target.checked_mul(size).ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
    if requested > control.ledger.available() { return Err(limit(LimitKind::ReservedBytes, offset)); }
    let mut values = Vec::new();
    values.try_reserve_exact(target).map_err(|_| oom(offset))?;
    let new_bytes = values.capacity().checked_mul(size).ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
    let old_bytes = old.capacity().checked_mul(size).ok_or_else(|| limit(LimitKind::Arithmetic, offset))?;
    let lease = control.ledger.admit(AllocationTag::None, new_bytes)?;
    Ok(Some(Replacement { values, lease, old_bytes, new_bytes }))
}

fn reconcile<T>(buffer: &Replacement<T>, control: &mut PaintControl<'_>) -> Result<()> {
    control.ledger.release(buffer.lease)?;
    let _job_lease = control.ledger.admit(AllocationTag::None, buffer.new_bytes - buffer.old_bytes)?;
    Ok(())
}
