    assert_eq!(ledger.stats().total_allocated_bytes - initial.total_allocated_bytes, cache.storage_bytes().unwrap());
    for index in 1..16 {
        resolve_cached_fill(&mut shared, &mut cache, &mut ledger, fill(), &edges(), affine_identity(), [10. + index as f64, 10.], &mut Run).unwrap();
