    let new_entries = 32 * std::mem::size_of::<GradientCacheEntry>();
    resolve_cached_fill(&mut shared, &mut cache, &mut ledger, fill(), &edges(), affine_identity(), [100., 10.], &mut Run).unwrap();
    let stop_bytes = cache.entries.last().unwrap().stops.capacity() * std::mem::size_of::<PaintStop>();
    assert!(ledger.stats().peak_live_bytes >= before_growth.live_bytes + new_entries + stop_bytes);
    assert_eq!(ledger.stats().live_bytes - initial.live_bytes, cache.storage_bytes().unwrap());
    assert_eq!(cache.entries.capacity(), 32);
}
