struct StopAt { remaining: usize, polls: usize }
impl StopAt {
    fn poll(&mut self) -> std::result::Result<(), Stop> {
        self.polls += 1;
        if self.remaining == 0 { Err(Stop::Canceled) } else { self.remaining -= 1; Ok(()) }
    }
}
impl WorkControl for StopAt {
    fn charge(&mut self, _: WorkKind, _: u64) -> std::result::Result<(), Stop> { self.poll() }
    fn checkpoint(&mut self) -> std::result::Result<(), Stop> { self.poll() }
}

